Console.WriteLine("=== PUBLIC TYPES IN MICROSOFT.AGENTS.AI ===\n");

var publicTypes = asm.GetTypes().Where(t => t.IsPublic).OrderBy(t => t.FullName);

foreach (var type in publicTypes)
{
    Console.WriteLine($"\n{type.FullName}");
    Console.WriteLine($"  Kind: {(type.IsInterface ? "Interface" : type.IsEnum ? "Enum" : type.IsClass ? "Class" : "Struct")}");

    // Constructors
    var ctors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
    if (ctors.Length > 0)
    {
        Console.WriteLine("  Constructors:");
        foreach (var ctor in ctors)
        {
            var parms = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            Console.WriteLine($"    .ctor({parms})");
        }
    }

    // Methods
    var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
        .Where(m => !m.IsSpecialName && m.DeclaringType == type)
        .OrderBy(m => m.Name);

    if (methods.Any())
    {
        Console.WriteLine("  Methods:");
        foreach (var method in methods)
        {
            var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            var returnType = method.ReturnType.Name;
            var isStatic = method.IsStatic ? "static " : "";
            Console.WriteLine($"    {isStatic}{returnType} {method.Name}({parms})");
        }
    }

    // Properties
    var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
        .Where(p => p.DeclaringType == type)
        .OrderBy(p => p.Name);

    if (props.Any())
    {
        Console.WriteLine("  Properties:");
        foreach (var prop in props)
        {
            var access = (prop.CanRead && prop.CanWrite) ? "get; set;" : prop.CanRead ? "get;" : "set;";
            Console.WriteLine($"    {prop.PropertyType.Name} {prop.Name} {{ {access} }}");
        }
    }
}
