using System;
using System.Reflection;
using System.Linq;

class Program
{
    static void Main()
    {
        InspectAssembly("Microsoft.Agents.AI");
        Console.WriteLine("\n\n" + new string('=', 80));
        Console.WriteLine("=== PUBLIC TYPES IN MICROSOFT.EXTENSIONS.AI ===");
        Console.WriteLine(new string('=', 80) + "\n");
        InspectAssembly("Microsoft.Extensions.AI");
    }

    static void InspectAssembly(string assemblyName)
    {
        Console.WriteLine($"=== PUBLIC TYPES IN {assemblyName} ===\n");

        var asm = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault(a => a.GetName().Name == assemblyName);
        if (asm == null)
        {
            try
            {
                asm = Assembly.Load(assemblyName);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading assembly: {ex.Message}");
                return;
            }
        }

        var publicTypes = asm.GetTypes()
            .Where(t => t.IsPublic)
            .OrderBy(t => t.FullName)
            .ToList();

        foreach (var type in publicTypes)
        {
            PrintType(type);
        }
    }

    static void PrintType(Type type)
    {
        Console.WriteLine($"\n{'[' + (type.IsInterface ? "Interface" : type.IsEnum ? "Enum" : type.IsClass ? "Class" : "Struct") + ']'} {type.FullName}");

        // Base types and interfaces
        if (type.BaseType != null && type.BaseType != typeof(object) && type.BaseType != typeof(ValueType))
        {
            Console.WriteLine($"  : {type.BaseType.FullName}");
        }
        var interfaces = type.GetInterfaces();
        if (interfaces.Length > 0)
        {
            foreach (var iface in interfaces)
            {
                Console.WriteLine($"  : {iface.FullName}");
            }
        }

        // Constructors
        var ctors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static);
        if (ctors.Length > 0)
        {
            foreach (var ctor in ctors)
            {
                var parms = FormatParameters(ctor.GetParameters());
                Console.WriteLine($"  .ctor({parms})");
            }
        }

        // Events
        var events = type.GetEvents(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
            .Where(e => e.DeclaringType == type)
            .OrderBy(e => e.Name);
        foreach (var evt in events)
        {
            Console.WriteLine($"  event {evt.EventHandlerType?.Name} {evt.Name}");
        }

        // Methods (excluding special methods like get_/set_)
        var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
            .Where(m => !m.IsSpecialName && m.DeclaringType == type)
            .OrderBy(m => m.Name);

        foreach (var method in methods)
        {
            var parms = FormatParameters(method.GetParameters());
            var returnType = method.ReturnType.Name;
            var isStatic = method.IsStatic ? "static " : "";
            var isAsync = method.ReturnType.Name.StartsWith("Task") ? " [async]" : "";
            Console.WriteLine($"  {isStatic}{returnType} {method.Name}({parms}){isAsync}");
        }

        // Properties
        var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
            .Where(p => p.DeclaringType == type)
            .OrderBy(p => p.Name);

        foreach (var prop in props)
        {
            var access = (prop.CanRead && prop.CanWrite) ? "get; set;" : prop.CanRead ? "get;" : "set;";
            Console.WriteLine($"  {prop.PropertyType.Name} {prop.Name} {{ {access} }}");
        }

        // Nested types
        var nestedTypes = type.GetNestedTypes(BindingFlags.Public)
            .OrderBy(t => t.Name);
        foreach (var nested in nestedTypes)
        {
            Console.WriteLine($"  [nested {(nested.IsInterface ? "Interface" : nested.IsEnum ? "Enum" : "Type")}] {nested.Name}");
        }
    }

    static string FormatParameters(ParameterInfo[] parms)
    {
        return string.Join(", ", parms.Select(p => 
        {
            var typeName = p.ParameterType.IsGenericType
                ? p.ParameterType.Name.Split('`')[0] + "<...>"
                : p.ParameterType.Name;
            return $"{typeName} {p.Name}";
        }));
    }
}
