class Program
{
    static void Main()
    {
        var asm = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault(a => a.GetName().Name == "Microsoft.Agents.AI");
        if (asm == null)
        {
            try
            {
                asm = Assembly.Load("Microsoft.Agents.AI");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
                return;
            }
        }

        // Find AIAgent base class
        var aiAgentType = asm.GetType("Microsoft.Agents.AI.AIAgent");
        if (aiAgentType != null)
        {
            Console.WriteLine($"AIAgent Type: {aiAgentType.FullName}");
            Console.WriteLine($"Is Abstract: {aiAgentType.IsAbstract}");
            Console.WriteLine($"Base Type: {aiAgentType.BaseType?.FullName}");
            Console.WriteLine($"\nMethods and Properties:");

            var methods = aiAgentType.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
                .Where(m => !m.IsSpecialName && m.DeclaringType == aiAgentType)
                .OrderBy(m => m.Name);

            foreach (var method in methods)
            {
                var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
                Console.WriteLine($"  {method.ReturnType.Name} {method.Name}({parms})");
            }

            var props = aiAgentType.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
                .Where(p => p.DeclaringType == aiAgentType)
                .OrderBy(p => p.Name);

            foreach (var prop in props)
            {
                Console.WriteLine($"  {prop.PropertyType.Name} {prop.Name}");
            }
        }
        else
        {
            Console.WriteLine("AIAgent type not found");
        }
    }
}
